-- Contexto do profissional para o encaminhamento: catálogo de competências com sinônimos e perfil de atendimento.
CREATE TABLE competency_catalog(tenant_id uuid NOT NULL REFERENCES tenants(id),code text NOT NULL CHECK(code ~ '^[a-z0-9_]{2,40}$'),name text NOT NULL,description text NOT NULL DEFAULT '',synonyms text[] NOT NULL DEFAULT '{}',specialties text[] NOT NULL DEFAULT '{}',offered boolean NOT NULL DEFAULT true,PRIMARY KEY(tenant_id,code));
) AS c(code,name,description,synonyms,specialties,offered) ON CONFLICT DO NOTHING;

CREATE TABLE professional_profiles(tenant_id uuid NOT NULL,professional_id uuid NOT NULL,
 bio text NOT NULL DEFAULT '' CHECK(length(bio)<=1500),
 approach text NOT NULL DEFAULT '' CHECK(length(approach)<=1500),
 target_conditions text[] NOT NULL DEFAULT '{}',
 excluded_profiles text NOT NULL DEFAULT '' CHECK(length(excluded_profiles)<=800),
 modalities text[] NOT NULL DEFAULT '{CLINIC}' CHECK(modalities<@ARRAY['CLINIC','HOME','ONLINE'] AND cardinality(modalities)>0),
 secondary_specialties text[] NOT NULL DEFAULT '{}',
 weekly_hours_available int CHECK(weekly_hours_available IS NULL OR weekly_hours_available BETWEEN 0 AND 60),
 accepts_new_patients boolean NOT NULL DEFAULT true,
 accepted_insurer_ids uuid[] NOT NULL DEFAULT '{}',
 ai_notes text NOT NULL DEFAULT '' CHECK(length(ai_notes)<=800),
 version int NOT NULL DEFAULT 1,updated_by uuid REFERENCES users(id),updated_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(tenant_id,professional_id),FOREIGN KEY(tenant_id,professional_id) REFERENCES professionals(tenant_id,id));
